"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7650],{54487:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"TechTreeGuiController","desc":"Drives `StarterGui.TechTreeGui`. Studio holds the panel plus one template\\nper repeated piece (the `Templates` folder). This controller clones a tab\\nper `ResearchConfig.Branches` entry and, for the open branch, a card per\\nnode, a connector Frame per line segment and a tier label per row, all\\nplaced by `TechTreeGuiRules` from each node\'s `Tier`, `Column` and\\n`Prereqs`. Adding a node or a branch is a config edit. Refuel is hold to\\ncharge, pay on release: `ReqResearchHold(true)` on the press freezes the\\nbench, the release sends `ReqResearchHold(false)` and one\\n`ReqResearchRefuel(points)`. A node behind a game pass the player lacks\\nturns the action button into BUY PASS, which opens the Roblox prompt.\\n\\nTwo layouts share this code: `MainContainer` (full) and `CompactContainer`\\n(phones and 4:3 tablets, when the full layout\'s scale drops below\\n`Rules.COMPACT_BELOW`). Both are bound into one `View`; `view` is the one\\non screen and every paint function reads it.","realm":["Client"],"source":{"line":22,"path":"src/StarterPlayer/StarterPlayerScripts/TechTreeGuiController.client.luau"}}')}}]);